WITH m AS (SELECT r.name AS division, date_trunc('month', o.order_at) AS month, SUM(COALESCE(o.total_bdt, o.total_amount * cr.bdt_per_unit)) AS gmv FROM orders o LEFT JOIN currency_rates cr ON cr.rate_date = CAST(o.order_at AS DATE) AND cr.currency = o.currency JOIN customer_addresses a ON a.address_id = o.address_id JOIN cities ci ON ci.city_id = a.city_id JOIN regions r ON r.region_id = ci.region_id WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' GROUP BY 1, 2) SELECT division, month, gmv, gmv / LAG(gmv) OVER (PARTITION BY division ORDER BY month) - 1 AS mom_growth FROM m ORDER BY division, month
